const first = $input.first()?.json || {};
if (first.error) {
  const msg = typeof first.error === 'string'
    ? first.error
    : (first.error.message || first.message || 'Google Sheets error');
  return [{
    json: {
      success: false,
      result: null,
      error: {
        type: 'EXTERNAL_SERVICE_ERROR',
        message: msg,
        retryable: true,
      },
    },
  }];
}

const data = $input.all().filter((item) => item.json && item.json.ruc_clpv);

function clean(value = '') {
  return String(value || '').replace(/<br\s*\/?>/gi, '').trim();
}

function extractSector(nomRouter = '') {
  const value = clean(nomRouter);
  if (!value) return '';
  const parts = value.split('-').map((p) => p.trim()).filter(Boolean);
  const ignored = ['MKT', 'MTD'];
  const sector = parts.find((p) => !ignored.includes(p.toUpperCase()));
  if (!sector) return '';
  return sector.toLowerCase().replace(/\s+/g, ' ').trim();
}

function extractOltName(nomOlt = '') {
  const value = clean(nomOlt).toUpperCase();
  if (!value) return '';
  if (value.startsWith('CDATA-')) return 'cData';
  if (value === 'SOLES_CDATA') return 'solesCData';
  if (value === 'SOLES_KINGTYPE') return 'solesKingtype';
  if (value === 'SANTA BARBARA') return 'santaBarbara';
  if (value === 'CALACALI') return 'calacali';
  if (value === 'PIFO') return 'pifo';
  if (value === 'POMASQUI') return 'pomasqui';
  if (value === 'BELLAVISTA') return 'bellavista';
  if (value === 'TOTORACOCHA') return 'totoracocha';
  return value.toLowerCase().replace(/\s+/g, ' ').trim();
}

function extractPon(ponOnu = '') {
  const match = String(ponOnu || '').match(/\/(\d+):/);
  return match ? match[1] : '';
}

function extractIp(ips = '') {
  const value = clean(ips);
  const match = value.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/);
  return match ? match[0] : '';
}

function buildContract(row, index = 0) {
  const sector = extractSector(row.nom_router);
  const ip = extractIp(row.ips);
  const contractCode = row.codigo ? String(row.codigo).trim() : undefined;
  const contractId = contractCode || (row.id ? String(row.id).trim() : (row.ruc_clpv ? String(row.ruc_clpv) + '-' + (index + 1) : String(index + 1)));
  const address = clean(row.direccion);
  const email = clean(row.email || row.correo);
  const phone = clean(row.telefono || row.celular);
  return {
    id: contractId,
    contractCode,
    name: clean(row.nom_clpv),
    address,
    email: email || undefined,
    phone: phone || undefined,
    label: address || (sector ? 'Sector ' + sector : 'Contrato #' + contractId),
    status: clean(row.estado),
    ip,
    router: {
      sector,
      olt_name: extractOltName(row.nom_olt),
      pon: extractPon(row.pon_onu),
      serial: clean(row.seriales),
      ip,
    },
  };
}

let contracts;
if (data.length <= 1) {
  contracts = data.map((item, idx) => buildContract(item.json, idx));
} else {
  const input = $('Webhook').first()?.json?.body?.input || {};
  const code = String(input.code || input.codigo || '').toLowerCase();
  const address = String(input.address || '').toLowerCase();
  const name = String(input.name || '').toLowerCase();
  const serial = input.serial;
  const filteredData = data.filter((item, idx) => {
    const row = item.json;
    const itemCode = String(row.codigo || row.id || (String(row.ruc_clpv) + '-' + (idx + 1))).toLowerCase();
    const itemName = String(row.nom_clpv || '').toLowerCase();
    const itemAddress = String(row.direccion || '').toLowerCase();
    const itemSerial = clean(row.seriales);
    const matchesCode = !code || itemCode === code || itemCode.includes(code);
    const matchesName = !name || itemName.includes(name);
    const matchesAddress = !address || itemAddress.includes(address);
    const matchesSerial = !serial || String(itemSerial) === String(serial);
    return matchesCode && matchesName && matchesAddress && matchesSerial;
  });
  const finalRows = (code || address || name || serial) && filteredData.length > 0 ? filteredData : data;
  contracts = finalRows.map((item, idx) => buildContract(item.json, idx));
}

const titularEmail = contracts.find((c) => c.email)?.email || clean(data.find((d) => d.json && (d.json.email || d.json.correo))?.json?.email);

return [{
  json: {
    success: true,
    result: {
      found: contracts.length > 0,
      contractNumbers: contracts.length,
      email: titularEmail || undefined,
      contracts,
    },
    error: null,
  },
}];
